INSERT OR IGNORE INTO articles (
  id, slug, title, meta_title, meta_description, summary, content,
  category, tags, author_name, author_url,
  status, published_at, updated_at, created_at, indexnow_sent,
  hero_image_url, key_takeaways, faq, reading_time_min
) VALUES (
  '01HZZZ00000000000000DEMOAR1',
  'bem-vindo-ao-blog',
  'Bem-vindo ao Blog Exemplo',
  'Bem-vindo ao Blog Exemplo | Conteúdo sobre IA e Tecnologia',
  'Conheça o Blog Exemplo: por que ele existe, o que você vai encontrar aqui e como o conteúdo é organizado.',
  'Este é um blog dedicado a explicar conceitos de IA, desenvolvimento moderno e arquitetura de software de forma clara, direta e otimizada para ser citada por mecanismos de busca generativa como Google AI Overviews e ChatGPT Search.',
  '<h2>O que você vai encontrar aqui</h2><p>Este blog publica conteúdo organizado em quatro áreas principais: fundamentos de IA, tutoriais práticos, decisões de arquitetura e novidades do ecossistema. Cada artigo é escrito com um padrão estrutural que prioriza respostas diretas, exemplos concretos e contexto suficiente para que tanto leitores humanos quanto sistemas de IA generativa possam extrair valor.</p><h2>Como o conteúdo é estruturado</h2><p>Todo artigo segue o mesmo padrão: um resumo de uma a duas frases logo abaixo do título, seguido por seções organizadas em perguntas e respostas. Esse formato é otimizado para os algoritmos modernos de busca generativa.</p><h3>Por que esse formato funciona</h3><ul><li><strong>Resumo no topo:</strong> é o trecho mais provável de ser citado por AI Overviews.</li><li><strong>Subtítulos como perguntas:</strong> casam diretamente com a forma como as pessoas pesquisam.</li><li><strong>Listas e tabelas:</strong> facilitam extração de dados estruturados.</li><li><strong>Links internos:</strong> mostram contexto e profundidade de cobertura.</li></ul><h2>Stack técnico</h2><p>Este blog roda em Astro com Cloudflare Workers e D1, com publicação via API. O foco é performance (TTFB sub-100ms na edge), SEO técnico impecável e zero JavaScript desnecessário no cliente.</p><h2>O que vem a seguir</h2><p>Os próximos artigos vão entrar em mais detalhes sobre cada uma dessas áreas. Use o campo de busca acima ou navegue pelas categorias para explorar.</p>',
  'novidades',
  '["lancamento","blog","seo","aio"]',
  'Equipe Editorial',
  'https://www.exemplo.com.br/equipe',
  'published',
  '2026-04-16T00:00:00.000Z',
  '2026-04-16T00:00:00.000Z',
  '2026-04-16T00:00:00.000Z',
  1,
  'https://picsum.photos/seed/blog-welcome/1200/630',
  '["Conteúdo é organizado em 4 categorias: IA, Tutoriais, Arquitetura, Novidades.","Todo artigo abre com resumo citável de 1–2 frases para AI Overviews.","Subtítulos em formato de pergunta casam com queries reais de busca.","Stack: Astro 6 + Cloudflare Workers + D1 + Drizzle ORM na edge.","Foco em SEO técnico, performance sub-100ms e zero JS desnecessário."]',
  '[{"q":"Quem mantém este blog?","a":"A equipe editorial publica novos artigos toda semana, com revisão técnica antes de publicação."},{"q":"Posso compartilhar os artigos com IA?","a":"Sim — cada artigo tem botões para abrir Perplexity, ChatGPT, Claude e Gemini com prompts pré-preenchidos."},{"q":"Qual a frequência de publicação?","a":"Em média 2–3 artigos por semana, distribuídos entre as quatro categorias."}]',
  4
);

INSERT OR IGNORE INTO articles (
  id, slug, title, meta_title, meta_description, summary, content,
  category, tags, author_name, author_url,
  status, published_at, updated_at, created_at, indexnow_sent,
  hero_image_url, key_takeaways, faq, reading_time_min
) VALUES (
  '01HZZZ00000000000000DEMOAR2',
  'edge-ssr-com-astro-e-d1',
  'Edge SSR com Astro 6 e Cloudflare D1: padrões e armadilhas',
  'Edge SSR com Astro 6 e D1 | Padrões de Cache e Latência',
  'Como montar SSR na edge com Astro 6 + Cloudflare D1 sem cair em armadilhas de cache, cold start e queries N+1.',
  'Astro 6 com adapter Cloudflare e D1 viabiliza SSR global sub-100ms, mas exige disciplina em cache HTTP, agregação de queries e uso correto de waitUntil para tarefas em background.',
  '<h2>Por que edge SSR ganha de SSG para conteúdo dinâmico</h2><p>SSG é imbatível para páginas que mudam pouco — você gera HTML uma vez e o CDN serve a velocidade da luz. Mas blogs com publicação frequente, listagem por categoria e busca pagam um preço alto: cada novo artigo dispara rebuild + redeploy. Em escala, isso vira o gargalo.</p><p>Edge SSR resolve isso renderizando sob demanda no datacenter mais perto do usuário. Com Cloudflare Workers + D1, o tempo até o primeiro byte fica em torno de 30–80ms globalmente, sem rebuild.</p><h2>Como configurar Astro 6 com adapter Cloudflare</h2><p>O ponto crítico é entender que Astro 6 mudou como o ambiente é exposto. A API antiga <code>Astro.locals.runtime.env</code> foi removida; agora você importa direto de <code>cloudflare:workers</code>.</p><h3>Bindings e platformProxy</h3><p>Em desenvolvimento, ative <code>platformProxy</code> no adapter para que <code>astro dev</code> tenha acesso ao D1 local via miniflare. Em produção, os bindings vêm direto do <code>wrangler.toml</code>.</p><h2>Padrões de cache que funcionam na edge</h2><p>Cache na edge é regido por headers HTTP padrão. As três regras que economizam mais dinheiro: <strong>(1)</strong> use <code>Cache-Control: public, max-age=N</code> generoso em rotas estáveis (sitemap, llms.txt, robots.txt); <strong>(2)</strong> use <code>no-store</code> em health checks; <strong>(3)</strong> nunca cache rotas autenticadas.</p><h2>Armadilhas comuns com D1</h2><p>D1 é SQLite na edge — a maior parte dos padrões SQL funciona, mas tem limites. Queries pesadas com <code>JOIN</code> em milhões de rows não escalam — prefira denormalização ou uma cache layer separada (KV ou Cache API). E lembre que cada query roda no datacenter de origem do D1, não na edge — isso adiciona ~30ms para usuários longe do datacenter primário.</p><h2>Tarefas em background com waitUntil</h2><p>Quando você publica um artigo, precisa pingar IndexNow e o sitemap do Google. Esses pings podem demorar 500ms — bloquear a resposta do publish é caro. A solução é <code>waitUntil()</code>: você devolve a resposta ao cliente imediatamente e o Worker continua executando o ping em background.</p>',
  'arquitetura',
  '["astro","cloudflare","edge","d1","ssr"]',
  'Equipe Editorial',
  'https://www.exemplo.com.br/equipe',
  'published',
  '2026-04-22T00:00:00.000Z',
  '2026-04-22T00:00:00.000Z',
  '2026-04-22T00:00:00.000Z',
  1,
  'https://picsum.photos/seed/edge-ssr-astro/1200/630',
  '["Astro 6 SSR + Cloudflare Workers entrega TTFB 30–80ms global sem rebuild.","API antiga Astro.locals.runtime.env foi removida — use import { env } from cloudflare:workers.","Cache-Control HTTP é a forma mais barata de baixar custo de Worker invocations.","D1 não escala JOIN pesado — denormalize ou use KV/Cache API como camada extra.","waitUntil() libera resposta enquanto pings IndexNow/Google rodam em background."]',
  '[{"q":"Edge SSR substitui SSG para sempre?","a":"Não. Páginas com conteúdo realmente estático ainda ganham com SSG ou ISR. Edge SSR brilha em listings dinâmicos, busca e personalização leve."},{"q":"Qual o limite prático do D1 hoje?","a":"D1 funciona bem até centenas de milhares de rows com queries simples. Acima disso, denormalize ou mude para Postgres gerenciado (Neon, Hyperdrive)."},{"q":"Como migrar de Astro 5 para 6 sem quebrar?","a":"O ponto mais frequente é o env: substitua Astro.locals.runtime.env por import direto de cloudflare:workers em todos os endpoints e middleware."},{"q":"Posso usar Drizzle ORM com D1?","a":"Sim — adicione compatibility_flags = [\"nodejs_compat\"] no wrangler.toml para o Drizzle conseguir importar node:async_hooks."}]',
  6
);

