INSERT OR IGNORE INTO articles (
  id, slug, title, meta_title, meta_description, summary, content,
  category, tags, author_name, author_url,
  status, published_at, updated_at, created_at, indexnow_sent,
  hero_image_url, key_takeaways, faq, reading_time_min
) VALUES (
  '01HZZZ00000000000000DEMOAR3',
  'como-llms-escolhem-o-que-citar',
  'Como LLMs escolhem o que citar — e como otimizar para isso',
  'Como LLMs Escolhem o Que Citar | Guia GEO',
  'Generative Engine Optimization explicado: por que LLMs citam algumas fontes mais que outras e como estruturar seu conteúdo para entrar no corpus de retrieval.',
  'LLMs como Perplexity, ChatGPT Search e Google AI Overviews citam fontes com base em três sinais combinados: clareza estrutural do conteúdo, autoridade do domínio e densidade de respostas auto-contidas em cada parágrafo.',
  '<h2>O que é GEO (Generative Engine Optimization)</h2><p>GEO é a prática de estruturar conteúdo para ser preferencialmente citado por motores de busca generativa. Não substitui SEO — é uma camada adicional que otimiza para um leitor diferente: o sistema de retrieval que monta a resposta de IA.</p><h2>Os três sinais que LLMs combinam para citar</h2><p>A pesquisa pública (papers de Perplexity, blog do Google sobre AI Overviews, observação empírica) converge em três sinais principais.</p><h3>1. Clareza estrutural</h3><p>Subtítulos em formato de pergunta, listas, tabelas e código formatado fazem o conteúdo ser fragmentado em chunks citáveis. Um artigo em parágrafos densos sem hierarquia clara perde quase sempre para um artigo com a mesma informação em listas e H2s objetivos.</p><h3>2. Autoridade percebida</h3><p>Backlinks ainda contam, mas LLMs também olham para sinais que o Google tradicional ignora: presença em datasets de treinamento citáveis, citações cruzadas em outros conteúdos do mesmo domínio, e correspondência semântica entre o conteúdo e o tópico declarado.</p><h3>3. Auto-contenção dos parágrafos</h3><p>Esse é o sinal mais subestimado. Cada parágrafo deve fazer sentido extraído isoladamente. Se um parágrafo só faz sentido depois de você ler os três anteriores, ele não vira citação.</p><h2>Como aplicar na prática</h2><p>Comece pelo resumo: as primeiras duas frases do artigo são a citação mais provável. Escreva-as como se fossem a resposta a uma pergunta direta. Em seguida, organize o corpo em H2s que sejam perguntas explícitas, e termine cada seção com uma frase que sintetize o ponto sem depender do contexto anterior.</p><h2>Métricas para acompanhar</h2><p>Hoje não existe Search Console para LLMs. O melhor proxy é monitorar manualmente: faça queries no Perplexity e ChatGPT Search relacionadas ao seu nicho e veja se seus artigos aparecem nas citações. Ferramentas como Otterly e Profound começam a oferecer monitoramento automatizado, mas ainda em estágio inicial.</p>',
  'ia-fundamentos',
  '["geo","llm","ai-overviews","perplexity","seo"]',
  'Equipe Editorial',
  'https://www.exemplo.com.br/equipe',
  'published',
  '2026-05-01T00:00:00.000Z',
  '2026-05-01T00:00:00.000Z',
  '2026-05-01T00:00:00.000Z',
  1,
  'https://picsum.photos/seed/llm-citation/1200/630',
  '["GEO otimiza conteúdo para retrieval de LLMs, não substitui SEO clássico.","Três sinais combinados decidem citação: estrutura, autoridade, auto-contenção.","Subtítulos em formato de pergunta convertem em chunks citáveis pelo LLM.","Cada parágrafo precisa fazer sentido isolado para ser elegível a citação.","Sem Search Console para LLMs ainda — monitore Perplexity e ChatGPT manualmente."]',
  '[{"q":"GEO vai substituir SEO?","a":"Não no curto prazo. Search tradicional ainda gera maior volume; GEO captura intenção de fundo de funil em queries informacionais complexas."},{"q":"Quanto tempo leva para um artigo virar citação em LLM?","a":"Varia. AI Overviews indexa em horas a dias; Perplexity pode demorar semanas para incluir um domínio novo no pool de fontes confiáveis."},{"q":"Preciso de schema.org especial para GEO?","a":"Não há schema dedicado, mas Article + FAQPage + BreadcrumbList ajudam o retriever a entender estrutura. Speakable é um bônus."},{"q":"E se o LLM citar errado meu conteúdo?","a":"Acontece. A defesa é ter resumo bem escrito no topo do artigo — quanto mais auto-contido, menor a chance de paráfrase imprecisa."}]',
  5
);

-- ════════════════════════════════════════════════════════════════════════════
-- AR4 — Guia completo de GEO em 2026 (categoria: ia-fundamentos)
-- Mission: seed-deepen-aiox-quartet-20260505-1400 / Phase 3 draft
-- Originality: 5/5 angles cleared (thesis_contrarian, internal_experience,
-- proprietary_data, practical_application, risk_pitfall)
-- ════════════════════════════════════════════════════════════════════════════
INSERT OR IGNORE INTO articles (
  id, slug, title, meta_title, meta_description, summary, content,
  category, tags, author_name, author_url,
  status, published_at, updated_at, created_at, indexnow_sent,
  hero_image_url, key_takeaways, faq, reading_time_min
) VALUES (
  '01HZZZ00000000000000DEMOAR4',
  'guia-completo-de-geo-em-2026',
  'Guia completo de GEO em 2026: pipeline operável de pesquisa a citation tracking',
  'Guia completo de GEO em 2026 | Pipeline GEO end-to-end',
  'GEO em 2026 deixou de ser teoria. Guia operável: pesquisa citation-first, esqueleto fixo, originality gate, verify-claims e citation tracking semanal.',
  'GEO (Generative Engine Optimization) é a disciplina de produzir conteúdo que LLMs como Perplexity, ChatGPT Search, Gemini e Google AI Overviews escolhem citar. Em 2026 deixou de ser teoria e virou pipeline operável: pesquisa citation-first, esqueleto fixo enforced, originality gate antes de publicar, verify-claims com pass rate mínimo, e citation tracking semanal por amostragem.',
  '<h2>Por que GEO virou disciplina autônoma em 2026?</h2><p>SEO clássico otimiza para um leitor humano que clica num link azul. GEO otimiza para um leitor diferente: o modelo de linguagem que monta a resposta sintetizando várias fontes, com ou sem o usuário visitar a página. Os dois compartilham fundamentos (clareza estrutural, autoridade, schema), mas divergem na unidade ótima de citação. SEO recompensa a página inteira ranqueada; GEO recompensa parágrafos individuais que sobrevivem extraídos do contexto e viram chunks de retrieval.</p><p>Essa divergência é o que justifica tratar GEO como disciplina própria. As métricas que medem sucesso, as decisões de estrutura, o ciclo de feedback — tudo muda quando o leitor passa a ser um sistema de retrieval. O Sinkra Hub formalizou essa divergência como um squad próprio (<code>content-geo</code>), separado dos squads de copy e SEO clássico, justamente porque o pipeline operacional é diferente o bastante para não caber dentro deles.</p><h2>O que separa GEO de SEO em métrica e unidade?</h2><p>SEO mede ranking de palavra-chave em SERP, CTR, tempo na página, pageviews. GEO mede taxa de citação por LLM, posição da citação na resposta sintetizada, share-of-voice em queries representativas do nicho. Hoje não existe Search Console para LLMs — toda métrica de citação é amostral, montada por execução periódica de queries no Perplexity, ChatGPT Search, Gemini e AI Overviews.</p><p>A unidade ótima também é diferente. Em SEO, a página inteira é o ativo. Em GEO, o parágrafo é o ativo. Um artigo SEO bem escrito com três blocos de raciocínio interconectado pode performar bem em ranking e mal em citação porque nenhum bloco isolado faz sentido sozinho. GEO força o autor a tornar cada parágrafo auto-contido — o que muitas vezes melhora também a leitura humana, mas obriga uma disciplina de redação que SEO não exige.</p><h2>Como funciona pesquisa citation-first?</h2><p>Pesquisa de keyword tradicional otimiza por volume de busca. Pesquisa citation-first adiciona dois filtros antes do volume: <strong>(1)</strong> a query força o LLM a consultar fonte externa, ou ele responde da memória? <strong>(2)</strong> as fontes citadas hoje em respostas do LLM são plurais, ou estão concentradas em três domínios fortes que ninguém vai deslocar? O primeiro filtro elimina queries de senso comum (modelo já tem na memória). O segundo elimina queries onde a competição é alta demais para um domínio novo entrar.</p><p>O resultado é uma lista de keywords menor, mais técnica, com volume médio-baixo, mas com taxa de inclusão em retrieval alta. Em nichos B2B técnicos, comparações específicas de ferramentas e tutoriais detalhados são tipicamente os formatos que mais aparecem em citação. Listicles genéricos do tipo "10 melhores ferramentas de X" perdem porque são derivativos por construção.</p><h2>O que entra no esqueleto fixo do artigo GEO?</h2><p>O esqueleto GEO não é estilo — é arquitetura de extração. No template canônico do hub, todo artigo renderizado em <code>/{slug}</code> tem a mesma estrutura visual: breadcrumb, H1, summary box com borda azul, meta-linha, AI share buttons, hero image, KeyTakeaways de 5 bullets, TableOfContents auto-gerado dos H2s, corpo, tags, FAQ e relacionados.</p><p>Cada bloco emite schema separado quando faz sentido: o artigo emite <code>Article</code>, o breadcrumb emite <code>BreadcrumbList</code>, o FAQ emite <code>FAQPage</code>. O summary box é marcado com <code>SpeakableSpecification</code> dentro do <code>Article</code> JSON-LD, sinalizando ao retriever que aquele trecho é o pedaço prioritário para AI Overviews e busca por voz. KeyTakeaways e FAQ são preenchidos como JSON arrays na própria tabela <code>articles</code> (<code>key_takeaways</code> e <code>faq</code>), não derivados do HTML — assim o retriever pode consumir os endpoints <code>/llms.txt</code> e <code>/llms-full.txt</code> e ter os mesmos chunks que estão na página, sem depender de parsing.</p><h2>Por que o originality gate é o gate mais importante?</h2><p>LLMs aprendem rápido a identificar conteúdo derivativo. Um artigo que apenas regurgita o que outras fontes já dizem perde para a fonte original — o retrieval prefere a fonte. O originality gate é uma checagem antes de publicar: o draft traz pelo menos um ângulo proprietário que nenhuma das fontes principais cobre? Se não traz, o artigo não vai ser citado, e publicar só polui o domínio com sinal fraco.</p><p>No squad <code>content-geo</code>, o gate é a Phase 2 do pipeline. Cinco categorias de ângulo proprietário são checadas: tese contrária à fonte, experiência interna do business, dado proprietário (benchmark, custo, breakeven), aplicação prática que a fonte não cobriu, e risco/armadilha que a fonte minimizou. O draft precisa clearar pelo menos três dos cinco. Falha em três significa HALT — o draft volta para retry com novo ângulo, ou escala para o operador decidir.</p><h2>Quais sinais técnicos importam (e quais não)?</h2><p>Os sinais que demonstrável fazem diferença em retrieval: <strong>(1)</strong> Schema.org Article + FAQPage + BreadcrumbList; <strong>(2)</strong> Sitemap.xml com <code>lastmod</code> preciso por artigo; <strong>(3)</strong> Endpoints no padrão llmstxt.org (<code>/llms.txt</code> índice + <code>/llms-full.txt</code> corpus); <strong>(4)</strong> Latência de carregamento abaixo de 2s na origem (LLMs com janela de retrieval timeout descartam fontes lentas); <strong>(5)</strong> Subdiretório em vez de subdomínio para consolidar autoridade.</p><p>Os sinais que importam menos do que a comunidade SEO clássica acredita: <strong>(1)</strong> Densidade de keyword exata; <strong>(2)</strong> Backlinks puros sem contexto; <strong>(3)</strong> Length de artigo isolada (LLM não bonifica artigo longo se cada chunk não for citável); <strong>(4)</strong> Schema decorativo (Person, ImageObject) sem amarrar com Article.</p><h2>Como medir GEO sem Search Console?</h2><p>O proxy operacional é amostragem. Você define 20–50 queries representativas do nicho e roda elas semanalmente nos quatro principais motores generativos: Google AI Overviews, Perplexity, ChatGPT Search, Gemini. Para cada query, registra se sua URL aparece como citação, em que posição, e qual o snippet citado. Em 8–12 semanas você tem uma curva de share-of-voice por motor.</p><p>Ferramentas comerciais como Profound e Otterly automatizam essa amostragem e expõem dashboard. O Sinkra Hub trata isso como skill do squad <code>content-geo</code> (<code>monitor-citations</code>) — na v1 do squad é amostral manual com checklist; v2 integra Profound/Otterly via API. A escolha de manter v1 manual é deliberada: ferramentas de monitoring estão em estágio inicial e cobrem apenas inglês com profundidade, então automação prematura traz mais ruído que sinal.</p><h2>Como GEO se compara com SEO clássico em cada dimensão?</h2><p>SEO e GEO compartilham fundamentos (clareza, autoridade, schema), mas divergem em métrica, unidade ótima e pipeline operacional. A tabela abaixo é o lado a lado completo nas 12 dimensões que mais separam os dois — não para escolher um, mas para saber onde cada um pesa.</p><h3>Top-line</h3><table><thead><tr><th>Atributo</th><th>SEO clássico</th><th>GEO</th></tr></thead><tbody><tr><td>Otimiza para</td><td>Crawler indexador → SERP</td><td>Retriever de LLM → resposta sintetizada</td></tr><tr><td>Unidade ótima</td><td>Página inteira</td><td>Parágrafo auto-contido</td></tr><tr><td>Métrica primária</td><td>Posição SERP + CTR</td><td>Citation rate + share-of-voice</td></tr><tr><td>Console oficial</td><td>Google Search Console</td><td>Não existe (proxies amostrais)</td></tr><tr><td>Stack típica</td><td>Schema + sitemap + backlinks</td><td>+ llms.txt + originality + latência <2s</td></tr><tr><td>Time-to-value</td><td>60–90d em domínio novo</td><td>60–90d + 2–3 sem com autoridade SEO prévia</td></tr></tbody></table><h3>Matriz por dimensão (12)</h3><table><thead><tr><th>#</th><th>Dimensão</th><th>SEO clássico</th><th>GEO</th></tr></thead><tbody><tr><td>1</td><td>Pesquisa de keyword</td><td>Volume + intenção comercial</td><td>Citation density + probabilidade de retrieval</td></tr><tr><td>2</td><td>Schema mínimo</td><td>Article + Breadcrumb</td><td>Article + FAQPage + Breadcrumb + Speakable</td></tr><tr><td>3</td><td>Sitemap</td><td>sitemap.xml</td><td>sitemap.xml + llms.txt + llms-full.txt</td></tr><tr><td>4</td><td>robots.txt</td><td>Allow + crawl hints</td><td>Allow: / explícito para LLM ingestion (ADR-026)</td></tr><tr><td>5</td><td>Originality</td><td>Editorial review</td><td>Blocking gate ≥3 de 5 ângulos</td></tr><tr><td>6</td><td>Verify factual</td><td>Editorial review</td><td>Exa+Firecrawl pass rate ≥85%</td></tr><tr><td>7</td><td>Backlinks</td><td>Sinal forte</td><td>Sinal indireto (autoridade de domínio)</td></tr><tr><td>8</td><td>Length ideal</td><td>1500–3000 palavras</td><td>Depende de auto-contenção, não de length</td></tr><tr><td>9</td><td>Cadência</td><td>2–4 artigos/semana</td><td>≤5/dia (NFR ceiling) — sinal fraco se acima</td></tr><tr><td>10</td><td>Monitoring</td><td>GSC + GA</td><td>Amostragem manual + Profound/Otterly</td></tr><tr><td>11</td><td>JS no cliente</td><td>Pouco impacto direto</td><td>>2s = exclusão de retrieval em motores agressivos</td></tr><tr><td>12</td><td>Schema decorativo</td><td>ItemList, Offer, ImageObject</td><td>SpeakableSpecification dominante</td></tr></tbody></table><h3>Equivalência (3 tier)</h3><table><thead><tr><th>Aspecto</th><th>Equivalência</th><th>Justificativa</th></tr></thead><tbody><tr><td>Clareza estrutural</td><td>Alta (4/5)</td><td>Ambos premiam H2 hierárquicos e listas</td></tr><tr><td>Schema técnico</td><td>Parcial (3/5)</td><td>Stack GEO inclui Speakable + llms.txt extras</td></tr><tr><td>Pesquisa de keyword</td><td>Sem equivalente (1/5)</td><td>Volume vs citation density são proxies diferentes</td></tr><tr><td>Métrica de sucesso</td><td>Sem equivalente (1/5)</td><td>SERP rank vs citation rate em LLM</td></tr><tr><td>Autoridade</td><td>Alta (4/5)</td><td>Ambos pesam autoridade de domínio</td></tr></tbody></table><p><strong>Verdict:</strong> SEO e GEO são pipelines complementares, não substituíveis em 2026. SEO ainda gera maior volume agregado de tráfego; GEO captura fundo de funil informacional complexo onde o LLM precisa consultar fonte externa. O estado da arte é manter os dois pipelines paralelos no mesmo domínio.</p><h2>Quais erros derrubam um pipeline GEO bem montado?</h2><p>Três armadilhas concretas que aparecem mesmo em pipelines bem desenhados. <strong>Tratar GEO como SEO 2.0:</strong> reaproveitar conteúdo SEO antigo sem reescrever para auto-contenção. O artigo aparece no SERP, mas LLMs não citam. <strong>Otimizar só para uma plataforma:</strong> tunar tudo para Perplexity hoje, e descobrir em três meses que AI Overviews ganhou volume e o site não foi pensado para ele. <strong>Ignorar latência:</strong> templates pesados em JavaScript no client (libraries de UI, hidratação completa) elevam o tempo até o primeiro byte e tiram o domínio do corpus de retrieval em motores com timeout agressivo.</p><p>Para todos os três, o template canônico do Sinkra Hub é uma resposta opinada: SSR na edge da Cloudflare, zero JavaScript no cliente fora da ilha de busca (Preact), e endpoints multi-LLM (<code>/llms.txt</code> + sitemap + robots.txt <code>Allow: /</code>) por padrão. Para detalhes da arquitetura, ver o artigo dedicado ao tour técnico do template.</p>',
